 342→          <p
 343→            style={{
 344→              fontSize: "13px",
 345→              fontWeight: 600,
 346→              color: "#6d7175",
 347→              textTransform: "uppercase",
 348→              letterSpacing: "0.5px",
 349→              margin: "0 0 10px",
 350→            }}
 351→          >
 352→            Start from scratch
 353→          </p>
 354→          <div
 355→            style={{
 356→              display: "inline-block",
 357→              border: `2px dashed ${hoveredCard === "__blank" ? "#005bd3" : "#c9cccf"}`,
 358→              borderRadius: "10px",
 359→              padding: "16px 24px",
 360→              background: hoveredCard === "__blank" ? "#f3f7ff" : "#f9fafb",
 361→              transition: "all 0.15s ease",
 362→              cursor: "pointer",
 363→              minWidth: "160px",
 364→            }}
 365→            onMouseEnter={() => setHoveredCard("__blank")}
 366→            onMouseLeave={() => setHoveredCard(null)}
 367→          >
 368→            <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
 369→              <div
 370→                style={{
 371→                  width: "40px",
 372→                  height: "40px",
 373→                  borderRadius: "50%",
 374→                  background: "#e4e5e7",
 375→                  display: "flex",
 376→                  alignItems: "center",
 377→                  justifyContent: "center",
 378→                  fontSize: "18px",
 379→                  flexShrink: 0,
 380→                }}
 381→              >
 382→                📋
 383→              </div>
 384→              <div>
 385→                <p
 386→                  style={{
 387→                    margin: "0 0 2px",
 388→                    fontWeight: 600,
 389→                    fontSize: "14px",
 390→                    color: "#202223",
 391→                  }}
 392→                >
 393→                  Blank chart
 394→                </p>
 395→                <p style={{ margin: 0, fontSize: "12px", color: "#6d7175" }}>
 396→                  Build with your own columns and sizes
 397→                </p>
 398→              </div>
 399→            </div>
 400→            <fetcher.Form method="post" style={{ marginTop: "12px" }}>
 401→              <input type="hidden" name="intent" value="create-blank" />
 402→              <input type="hidden" name="name" value="Untitled Size Chart" />
