 408→          </div>
 409→        </div>
 410→
 411→        {/* Templates by category */}
 412→        <div>
 413→          <p
 414→            style={{
 415→              fontSize: "13px",
 416→              fontWeight: 600,
 417→              color: "#6d7175",
 418→              textTransform: "uppercase",
 419→              letterSpacing: "0.5px",
 420→              margin: "0 0 16px",
 421→            }}
 422→          >
 423→            By category
