 531→export default function SizeCharts() {
 532→  const { charts, plan, templates, categories, canCreate } =
 533→    useLoaderData<typeof loader>();
 534→  const fetcher = useFetcher<typeof action>();
 535→  const shopify = useAppBridge();
 536→
 537→  const [showTemplates, setShowTemplates] = useState(false);
 538→  const [showImport, setShowImport] = useState(false);
 539→  const [importName, setImportName] = useState("Imported Size Chart");
 540→  const [importCategory, setImportCategory] = useState("general");
 541→  const [importCsvText, setImportCsvText] = useState("");
 542→  const [statusFilter, setStatusFilter] = useState<"all" | "active" | "draft">("all");
 543→  const [categoryFilter, setCategoryFilter] = useState("all");
 544→  const [searchQuery, setSearchQuery] = useState("");
 545→
 546→  const isLoading = fetcher.state !== "idle";
 547→
 548→  useEffect(() => {
 549→    if (!fetcher.data) return;
 550→    const data = fetcher.data as ActionData;
 551→    if ("ok" in data && data.ok) {
 552→      shopify.toast.show(data.message);
 553→      if ("redirectId" in data && data.redirectId) {
 554→        window.location.href = `/app/size-charts/${data.redirectId}`;
 555→      } else {
 556→        setShowTemplates(false);
 557→        setShowImport(false);
 558→        setImportCsvText("");
 559→        setImportName("Imported Size Chart");
 560→      }
 561→    } else if ("error" in data) {
 562→      shopify.toast.show(data.error, { isError: true });
 563→    }
 564→  }, [fetcher.data, shopify]);
 565→
 566→  const filteredCharts = charts.filter((chart) => {
 567→    const matchesStatus = statusFilter === "all" || chart.status === statusFilter;
 568→    const matchesCategory = categoryFilter === "all" || chart.category === categoryFilter;
 569→    const matchesSearch =
 570→      searchQuery.trim() === "" ||
 571→      chart.name.toLowerCase().includes(searchQuery.toLowerCase());
 572→    return matchesStatus && matchesCategory && matchesSearch;
 573→  });
 574→
 575→  const publishedCount = charts.filter((c) => c.status === "active").length;
 576→  const draftCount = charts.filter((c) => c.status === "draft").length;
 577→  const activeFilteredCount = charts.filter((c) => c.status === "active").length;
 578→  const draftFilteredCount = charts.filter((c) => c.status === "draft").length;
 579→  const maxCharts = plan.limits.maxCharts;
 580→  const isFreePlan = plan.id === "free";
 581→
 582→  const progressPct =
 583→    maxCharts > 0 ? Math.min(100, Math.round((publishedCount / maxCharts) * 100)) : 0;
 584→  const progressColor =
 585→    publishedCount >= maxCharts && maxCharts > 0 ? "#d72c0d" : "#1a73e8";
 586→
 587→  function clearFilters() {
 588→    setStatusFilter("all");
 589→    setCategoryFilter("all");
 590→    setSearchQuery("");
 591→  }
 592→
 593→  return (
 594→    <s-page heading="Size Charts">
 595→      {/* Primary action */}
 596→      <s-button
 597→        slot="primary-action"
 598→        variant="primary"
 599→        onClick={() => setShowTemplates(!showTemplates)}
 600→        disabled={!canCreate || isLoading}
 601→      >
 602→        {canCreate
 603→          ? showTemplates
 604→            ? "Cancel"
 605→            : "Create chart"
 606→          : `Limit reached (${plan.limits.maxCharts})`}
 607→      </s-button>
 608→
 609→      <s-button
 610→        slot="secondary-action"
 611→        onClick={() => { setShowImport(!showImport); setShowTemplates(false); }}
 612→      >
 613→        Import CSV
 614→      </s-button>
 615→
 616→      {/* Subtitle */}
 617→      <s-text tone="neutral">
 618→        Manage your size charts and assign them to products
 619→      </s-text>
 620→
 621→      {/* ================================================================ */}
 622→      {/* PLAN LIMIT BANNER                                                 */}
 623→      {/* ================================================================ */}
 624→      {!canCreate && (
 625→        <s-section>
