import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
import db from "../db.server";

// ---------------------------------------------------------------------------
// CORS
// ---------------------------------------------------------------------------

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
};

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

const SHOP_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface RecommendRequestBody {
  shop: string;
  chartId: string;
  height: number;
  weight: number;
  unit: "metric" | "imperial";
  gender: "male" | "female" | "unisex";
  bodyType: "slim" | "average" | "athletic" | "plus";
}

interface EstimatedMeasurements {
  chest: number;
  waist: number;
  hips: number;
  inseam: number;
}

interface SizeConfidence {
  size: string;
  confidence: number;
}

interface RecommendResponse {
  recommendedSize: string;
  confidence: number;
  alternatives: SizeConfidence[];
  measurements: EstimatedMeasurements;
}

interface ChartData {
  headers: string[];
  units: { default: string; available: string[] };
  rows: Record<string, string>[];
}

// ---------------------------------------------------------------------------
// Body proportion model
// Based on standard anthropometric body measurement ratios.
// Returns estimated measurements in inches.
// ---------------------------------------------------------------------------

function estimateMeasurements(
  heightIn: number,
  weightLbs: number,
  gender: RecommendRequestBody["gender"],
  bodyType: RecommendRequestBody["bodyType"],
): EstimatedMeasurements {
  // BMI-based body shape coefficient
  const heightFt = heightIn / 12;
  const bmi = (weightLbs / (heightFt * heightFt)) * 703;

  // Base proportions derived from published anthropometric studies (ANSUR II)
  // Chest = height * ratio + weight modifier
  const bodyTypeModifiers: Record<
    RecommendRequestBody["bodyType"],
    { chest: number; waist: number; hips: number }
  > = {
    slim: { chest: -1.5, waist: -1.5, hips: -1.5 },
    average: { chest: 0, waist: 0, hips: 0 },
    athletic: { chest: 1.5, waist: -1.0, hips: 0.5 },
    plus: { chest: 2.5, waist: 3.0, hips: 3.0 },
  };

  const mod = bodyTypeModifiers[bodyType];

  // Gender-specific base ratios
  const isFemale = gender === "female";

  // Chest estimation: height coefficient + BMI scaling
  const baseChest = isFemale
    ? heightIn * 0.485 + bmi * 0.3
    : heightIn * 0.52 + bmi * 0.28;

  // Waist: smaller ratio than chest, more BMI-sensitive
  const baseWaist = isFemale
    ? heightIn * 0.38 + bmi * 0.38
    : heightIn * 0.42 + bmi * 0.36;

  // Hips: slightly larger for female, similar to chest for male
  const baseHips = isFemale
    ? heightIn * 0.52 + bmi * 0.32
    : heightIn * 0.49 + bmi * 0.28;

  // Inseam: roughly 45-47% of height
  const baseInseam = heightIn * (isFemale ? 0.454 : 0.47);

  return {
    chest: Math.round((baseChest + mod.chest) * 10) / 10,
    waist: Math.round((baseWaist + mod.waist) * 10) / 10,
    hips: Math.round((baseHips + mod.hips) * 10) / 10,
    inseam: Math.round(baseInseam * 10) / 10,
  };
}

// ---------------------------------------------------------------------------
// Convert height/weight to inches/lbs (imperial baseline)
// ---------------------------------------------------------------------------

function toImperial(
  height: number,
  weight: number,
  unit: RecommendRequestBody["unit"],
): { heightIn: number; weightLbs: number } {
  if (unit === "imperial") {
    return { heightIn: height, weightLbs: weight };
  }
  // metric: height in cm, weight in kg
  return {
    heightIn: height / 2.54,
    weightLbs: weight * 2.20462,
  };
}

// ---------------------------------------------------------------------------
// Parse a measurement string like "34-36" or "34" into a numeric midpoint
// ---------------------------------------------------------------------------

function parseMeasurement(raw: string): number | null {
  if (!raw || typeof raw !== "string") return null;
  const cleaned = raw.trim().replace(/[^\d.-]/g, " ").trim();
  const parts = cleaned.split(/[\s-]+/).filter((p) => p.length > 0);
  const nums = parts.map(Number).filter((n) => !isNaN(n) && n > 0);
  if (nums.length === 0) return null;
  if (nums.length === 1) return nums[0];
  // Average of range
  return nums.reduce((a, b) => a + b, 0) / nums.length;
}

// ---------------------------------------------------------------------------
// Score a single chart row against estimated measurements
// Returns a confidence score 0–1
// ---------------------------------------------------------------------------

function scoreRow(
  row: Record<string, string>,
  measurements: EstimatedMeasurements,
  chartUnitsDefault: string,
): number {
  // Convert measurements to cm if the chart uses cm
  const factor = chartUnitsDefault === "cm" ? 2.54 : 1;
  const target = {
    chest: measurements.chest * factor,
    waist: measurements.waist * factor,
    hips: measurements.hips * factor,
    inseam: measurements.inseam * factor,
  };

  // Map column names (case-insensitive) to measurement types
  const COLUMN_MAP: Record<string, keyof typeof target> = {
    chest: "chest",
    bust: "chest",
    waist: "waist",
    hips: "hips",
    hip: "hips",
    inseam: "inseam",
  };

  let totalScore = 0;
  let scoredColumns = 0;

  for (const [colName, cellValue] of Object.entries(row)) {
    const normalised = colName.toLowerCase().replace(/[^a-z]/g, "");
    const measureKey = COLUMN_MAP[normalised];
    if (!measureKey) continue;

    const measured = parseMeasurement(cellValue);
    if (measured === null) continue;

    const actual = target[measureKey];
    // Tolerance: ±2in (or ±5cm) scores 1.0, degrades linearly to 0 at ±6in (±15cm)
    const tol = chartUnitsDefault === "cm" ? 5 : 2;
    const maxDelta = chartUnitsDefault === "cm" ? 15 : 6;
    const delta = Math.abs(actual - measured);
    const colScore = delta <= tol ? 1.0 : Math.max(0, 1 - (delta - tol) / (maxDelta - tol));

    totalScore += colScore;
    scoredColumns++;
  }

  if (scoredColumns === 0) return 0;
  return totalScore / scoredColumns;
}

// ---------------------------------------------------------------------------
// Main recommendation engine
// ---------------------------------------------------------------------------

function recommendSize(
  chartData: ChartData,
  measurements: EstimatedMeasurements,
): { recommendedSize: string; confidence: number; alternatives: SizeConfidence[] } {
  const sizeHeader = chartData.headers.find((h) =>
    ["size", "size label", "label"].includes(h.toLowerCase()),
  );

  if (!sizeHeader || chartData.rows.length === 0) {
    return { recommendedSize: "N/A", confidence: 0, alternatives: [] };
  }

  const unitsDefault = chartData.units?.default ?? "in";

  // Score each row
  const scored: SizeConfidence[] = chartData.rows
    .map((row) => {
      const sizeName = row[sizeHeader];
      if (!sizeName) return null;
      const confidence = Math.round(scoreRow(row, measurements, unitsDefault) * 100) / 100;
      return { size: sizeName, confidence };
    })
    .filter((s): s is SizeConfidence => s !== null);

  if (scored.length === 0) {
    return { recommendedSize: "N/A", confidence: 0, alternatives: [] };
  }

  // Sort descending by confidence
  scored.sort((a, b) => b.confidence - a.confidence);

  const best = scored[0];
  // Alternatives: second and third best with confidence > 0.3
  const alternatives = scored
    .slice(1)
    .filter((s) => s.confidence > 0.3)
    .slice(0, 2);

  return {
    recommendedSize: best.size,
    confidence: best.confidence,
    alternatives,
  };
}

// ---------------------------------------------------------------------------
// Preflight
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  if (request.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }
  return Response.json(
    { error: "Method not allowed" },
    { status: 405, headers: CORS_HEADERS },
  );
};

// ---------------------------------------------------------------------------
// Action — POST /api/recommend
// Body JSON: { shop, height, weight, unit, gender, bodyType, chartId }
// ---------------------------------------------------------------------------

export const action = async ({ request }: ActionFunctionArgs) => {
  if (request.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }

  if (request.method !== "POST") {
    return Response.json(
      { error: "Method not allowed" },
      { status: 405, headers: CORS_HEADERS },
    );
  }

  let body: Partial<RecommendRequestBody>;

  try {
    body = (await request.json()) as Partial<RecommendRequestBody>;
  } catch {
    return Response.json(
      { error: "Invalid JSON body" },
      { status: 400, headers: CORS_HEADERS },
    );
  }

  const { shop, chartId, height, weight, unit, gender, bodyType } = body;

  // Validate shop
  if (!shop || !SHOP_RE.test(shop)) {
    return Response.json(
      { error: "Invalid or missing shop parameter" },
      { status: 400, headers: CORS_HEADERS },
    );
  }

  // Validate required fields
  if (!chartId) {
    return Response.json(
      { error: "chartId is required" },
      { status: 400, headers: CORS_HEADERS },
    );
  }
  if (typeof height !== "number" || height <= 0) {
    return Response.json(
      { error: "height must be a positive number" },
      { status: 400, headers: CORS_HEADERS },
    );
  }
  if (typeof weight !== "number" || weight <= 0) {
    return Response.json(
      { error: "weight must be a positive number" },
      { status: 400, headers: CORS_HEADERS },
    );
  }
  if (!unit || !["metric", "imperial"].includes(unit)) {
    return Response.json(
      { error: "unit must be 'metric' or 'imperial'" },
      { status: 400, headers: CORS_HEADERS },
    );
  }
  if (!gender || !["male", "female", "unisex"].includes(gender)) {
    return Response.json(
      { error: "gender must be 'male', 'female', or 'unisex'" },
      { status: 400, headers: CORS_HEADERS },
    );
  }
  if (!bodyType || !["slim", "average", "athletic", "plus"].includes(bodyType)) {
    return Response.json(
      { error: "bodyType must be 'slim', 'average', 'athletic', or 'plus'" },
      { status: 400, headers: CORS_HEADERS },
    );
  }

  try {
    // Check recommender is enabled for this shop
    const recommenderConfig = await db.recommenderConfig.findUnique({
      where: { shop },
    });

    if (!recommenderConfig?.enabled) {
      return Response.json(
        { error: "AI recommender is not enabled for this shop" },
        { status: 403, headers: CORS_HEADERS },
      );
    }

    // Fetch the chart scoped to this shop
    const chart = await db.sizeChart.findFirst({
      where: { id: chartId, shop, status: "active" },
    });

    if (!chart) {
      return Response.json(
        { error: "Chart not found" },
        { status: 404, headers: CORS_HEADERS },
      );
    }

    // Parse chart data
    let chartData: ChartData;
    try {
      const parsed = JSON.parse(chart.data) as unknown;
      if (
        parsed !== null &&
        typeof parsed === "object" &&
        !Array.isArray(parsed)
      ) {
        const obj = parsed as Record<string, unknown>;
        chartData = {
          headers: Array.isArray(obj.headers) ? (obj.headers as string[]) : [],
          units:
            obj.units !== null &&
            typeof obj.units === "object" &&
            !Array.isArray(obj.units)
              ? (obj.units as { default: string; available: string[] })
              : { default: "in", available: ["in", "cm"] },
          rows: Array.isArray(obj.rows)
            ? (obj.rows as Record<string, string>[])
            : [],
        };
      } else {
        chartData = { headers: [], units: { default: "in", available: ["in", "cm"] }, rows: [] };
      }
    } catch {
      chartData = { headers: [], units: { default: "in", available: ["in", "cm"] }, rows: [] };
    }

    // Convert inputs to imperial baseline
    const { heightIn, weightLbs } = toImperial(height, weight, unit);

    // Estimate body measurements
    const effectiveGender: RecommendRequestBody["gender"] =
      gender === "unisex" ? "average" as unknown as RecommendRequestBody["gender"] : gender;

    const measurements = estimateMeasurements(
      heightIn,
      weightLbs,
      effectiveGender === ("average" as unknown as RecommendRequestBody["gender"])
        ? "female"
        : effectiveGender,
      bodyType,
    );

    // Run recommendation
    const { recommendedSize, confidence, alternatives } = recommendSize(
      chartData,
      measurements,
    );

    const response: RecommendResponse = {
      recommendedSize,
      confidence,
      alternatives,
      measurements,
    };

    return Response.json(response, { headers: CORS_HEADERS });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Internal server error";
    return Response.json(
      { error: message },
      { status: 500, headers: CORS_HEADERS },
    );
  }
};

import type { LoaderFunctionArgs } from "react-router";
import db from "../db.server";

// ---------------------------------------------------------------------------
// CORS
