const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
};

// ---------------------------------------------------------------------------
// Cache
// ---------------------------------------------------------------------------

const CACHE_MAX_AGE = 300; // 5 minutes

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

const SHOP_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;

// ---------------------------------------------------------------------------
// Default widget config
// Mirrors WidgetConfig Prisma model defaults exactly
// ---------------------------------------------------------------------------

const WIDGET_CONFIG_DEFAULTS = {
  displayMode: "popup",
  position: "bottom-right",
  triggerType: "button",
  primaryColor: "#000000",
  successColor: "#16a34a",
  errorColor: "#dc2626",
  backgroundColor: "#ffffff",
  textColor: "#111111",
  borderRadius: "8",
  heading: "Size Guide",
  placeholder: "Select your size",
  buttonText: "Find My Size",
  successMessage: "This size should fit you well!",
  errorMessage:
    "We couldn't determine your size. Please refer to the chart.",
  showRecommender: true,
  customCss: "",
} as const;

// ---------------------------------------------------------------------------
// Loader — GET /api/widget-config
// Query params: shop (required)
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  if (request.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }

  const url = new URL(request.url);
  const shop = url.searchParams.get("shop");

  if (!shop || !SHOP_RE.test(shop)) {
    return Response.json(
      { error: "Invalid or missing shop parameter" },
      { status: 400, headers: CORS_HEADERS },
    );
  }

  try {
    const config = await db.widgetConfig.findUnique({ where: { shop } });

    const responseHeaders = {
      ...CORS_HEADERS,
      "Cache-Control": `public, max-age=${CACHE_MAX_AGE}`,
    };

    if (!config) {
      // Return defaults when no config has been saved yet
      return Response.json(
        { config: WIDGET_CONFIG_DEFAULTS },
        { headers: responseHeaders },
      );
    }

    return Response.json(
      {
        config: {
          displayMode: config.displayMode,
          position: config.position,
          triggerType: config.triggerType,
          primaryColor: config.primaryColor,
          successColor: config.successColor,
          errorColor: config.errorColor,
          backgroundColor: config.backgroundColor,
          textColor: config.textColor,
          borderRadius: config.borderRadius,
          heading: config.heading,
          placeholder: config.placeholder,
          buttonText: config.buttonText,
          successMessage: config.successMessage,
          errorMessage: config.errorMessage,
          showRecommender: config.showRecommender,
          customCss: config.customCss,
        },
      },
      { headers: responseHeaders },
    );
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Internal server error";
    return Response.json(
      { error: message },
      { status: 500, headers: CORS_HEADERS },
    );
  }
};

import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
import db from "../db.server";

// ---------------------------------------------------------------------------
// CORS
