input.new_string:
// Convert inputs to imperial baseline
const { heightIn, weightLbs } = toImperial(height, weight, unit);

// Map unisex → female as a neutral default (average body proportions)
const calcGender: GenderCalc = gender === "male" ? "male" : "female";

// Estimate body measurements
const measurements = estimateMeasurements(
  heightIn,
  weightLbs,
  calcGender,
  bodyType,
);
